/// <summary>
/// MPJ_24248 Pricing Data Extract
/// </summary>
[ExtensionOf(tableStr(MarkupAutoLine))]
final public class METMarkupAutoLineTbl_Extension
{
}

Method.Source:
/// <summary>
/// Get the MarkupTable for this Line
/// </summary>
/// <returns>Markup table record</returns>
public MarkupAutoTable metMarkupTable()
{
    MarkupAutoTable metMarkupAutoTable;

    select firstonly metMarkupAutoTable
        where   metMarkupAutoTable.recId    == this.TableRecId
        &&      metMarkupAutoTable.TableId  == this.TableTableId;

    return metMarkupAutoTable;
}

/// <summary>
/// Find method. Std method is marked as Internal
/// </summary>
/// <param name = "_recId">ID</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>Markup Line record</returns>
public static MarkupAutoLine metFindByRecId(RecId _recId, boolean _forUpdate = false)
{
    MarkupAutoLine metMarkupAutoLine;

    if(_recId)
    {
        metMarkupAutoLine.selectForUpdate(_forUpdate);

        select firstonly metMarkupAutoLine
            where metMarkupAutoLine.recId == _recId;
    }
    return metMarkupAutoLine;
}

/// <summary>
/// CB748_PricingConditions
/// Add validation for custom rebate fields
/// </summary>
/// <returns>True if record validation successful; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (this.markupTable().METIsOffRemittance
    &&  this.ModuleType == MarkupModuleType::Vend 
    &&  this.ModuleCategory == HeadingLine::Line)
    {
        if (!this.METPurchGroupId)
        {
            ret = checkFailed(strFmt("@SYS26332", fieldPName(MarkupAutoLine, METPurchGroupId)));
        }

        ret = this.METValidateMarkupCodeRebateOverlap() && ret;
    }

    return ret;
}

/// <summary>
/// CB748_PricingConditions 
/// Validate if there is a date overlap with an existing auto charge line for the same header, charges code and purchase group
/// </summary>
/// <returns>True if there is an overlap; otherwise, false</returns>
public boolean METValidateMarkupCodeRebateOverlap()
{
    boolean ret = true;
    MarkupAutoLine  markupAutoLine;

    select firstonly MarkupCode, METPurchGroupId, FromDate, ToDate from markupAutoLine
                              where markupAutoLine.RecId           != this.RecId
                                 && markupAutoLine.TableTableId    == this.TableTableId
                                 && markupAutoLine.TableRecId      == this.TableRecId
                                 && markupAutoLine.MarkupCode      == this.MarkupCode
                                 && markupAutoLine.METPurchGroupId == this.METPurchGroupId
                                     && ((markupAutoLine.FromDate      >= this.FromDate
                                     && markupAutoLine.ToDate          >= this.ToDate
                                     && (markupAutoLine.FromDate        <= this.ToDate || this.ToDate == dateNull()))
                                     || (markupAutoLine.FromDate       <= this.FromDate
                                     && markupAutoLine.ToDate          >= this.FromDate
                                     && (markupAutoLine.FromDate        <= this.ToDate || this.ToDate == dateNull())
                                     && (markupAutoLine.ToDate          >= this.ToDate || this.ToDate == dateNull()))
                                     || (markupAutoLine.FromDate       <= this.FromDate
                                     && markupAutoLine.ToDate          >= this.FromDate
                                     && (markupAutoLine.ToDate          <= this.ToDate || this.ToDate == dateNull())));

    if (markupAutoLine)
    {
        ret = checkFailed(strFmt("@MET:ValidateMarkupCodeRebateOverlap", markupAutoLine.MarkupCode,
                                                                         markupAutoLine.METPurchGroupId,
                                                                         markupAutoLine.FromDate,
                                                                         markupAutoLine.ToDate));
    }        

    return ret;
}

/// <summary>
/// CB748_PricingConditions 
/// Extension to close previous period after insert
/// </summary>
public void insert()
{
    next insert();

    // after record is inserted, update the previous setup line with same charges code and purchase group end date
    this.METClosePreviousPeriod();
}

/// <summary>
/// CB748_PricingConditions
/// Close auto charge line from previous period if To date is empty and refresh datasource
/// </summary>
void METClosePreviousPeriod()
{
    MarkupAutoLine  markupAutoLine;

    // find if there is a record from previous period without a To date
    select firstonly markupAutoLine
        where markupAutoLine.RecId           != this.RecId
        && markupAutoLine.ModuleType    == this.ModuleType
        && markupAutoLine.ModuleCategory      == this.ModuleCategory
        && markupAutoLine.TableTableId    == this.TableTableId
        && markupAutoLine.TableRecId      == this.TableRecId
        && markupAutoLine.MarkupCode      == this.MarkupCode
        && markupAutoLine.METPurchGroupId == this.METPurchGroupId
        && markupAutoLine.FromDate      <= this.FromDate
        && markupAutoLine.ToDate        == dateNull();

    if (markupAutoLine)
    {
        ttsbegin;
        markupAutoLine.selectForUpdate(true);
        markupAutoLine.ToDate = this.FromDate - 1;
        markupAutoLine.update();
        ttscommit;

        if (FormDataUtil::isFormDataSource(this))
        {
            // refresh datasource
            FormDataUtil::getFormDataSource(this).research(true);
        }
    }
}
